-- bd/assoc/seed_competences_secondaire.sql
-- Gabarit des COMPETENCES par matiere / niveau / trimestre d'une école
-- secondaire (contenu réel de LAM_ABZ). competence.id_trim pointe vers un
-- trimestre d'UNE année scolaire : supprimer l'année (ou vider la base)
-- supprime donc ses compétences (ON DELETE CASCADE). Ce gabarit est indexé
-- par libellé de matière + code niveau + ORDRE du trimestre (1..3), donc
-- indépendant de toute année. appliquer_competences_ref_secondaire()
-- (fonctions.php) le rejoue sur les trimestres d'une année donnée, en
-- remplaçant :ID_ANNEE: par l'id de l'année. Idempotent (NOT EXISTS).
INSERT INTO `competence` (`id_matiere`, `code_niveau`, `id_trim`, `libelle`, `libelle_en`, `ordre`)
SELECT m.`id`, v.`code_niveau`, t.`id`, v.`libelle`, v.`libelle_en`, v.`ordre`
FROM (VALUES
